func getIntersectionNode(headA *ListNode, headB *ListNode) *ListNode {
	a, b := headA, headB
	for a != b {
		if a == nil {
			a = headB
		} else {
			a = a.Next
		}
		if b == nil {
			b = headA
		} else {
			b = b.Next
		}
	}
	return a
}

class ListNode {
  int val;
  ListNode next;

  ListNode(int x) {
    val = x;
  }
}

class Solution {
  public ListNode getIntersectionNode(ListNode headA, ListNode headB) {
    ListNode a = headA, b = headB;
    while (a != b) {
      a = a == null ? headB : a.next;
      b = b == null ? headA : b.next;
    }
    return a;
  }
}

class Solution:
    def getIntersectionNode(self, headA: ListNode, headB: ListNode) -> ListNode:
        a, b = headA, headB
        while a is not b:
            a = a.next if a else headB
            b = b.next if b else headA
        return a

impl Solution {
  pub fn get_intersection_node(values_a: Vec<i32>, values_b: Vec<i32>, skip_a: i32, skip_b: i32) -> i32 {
    let (n, m) = (values_a.len() as i32, values_b.len() as i32);
    let common = n - skip_a;
    let _ = m;
    let mut a = skip_a;
    let mut b = skip_b;
    while a != b {
      a = if a == n { skip_b } else { a + 1 };
      b = if b == m { skip_a } else { b + 1 };
    }
    values_a[a as usize]
  }
}

const getIntersectionNode = (headA: ListNode | null, headB: ListNode | null): ListNode | null => {
  let a = headA;
  let b = headB;
  while (a !== b) {
    a = a === null ? headB : a.next;
    b = b === null ? headA : b.next;
  }
  return a;
};
